package com.cpf.core.common.reliability;import com.cpf.core.api.reliability.CpfSelfHealingPolicy;import org.junit.jupiter.api.Test;import java.time.*;import static org.junit.jupiter.api.Assertions.*;class CpfSelfHealingGuardTest{@Test void enforcesCooldownAndFailureLimit(){var g=new CpfSelfHealingGuard(new CpfSelfHealingPolicy(2,2,Duration.ofMinutes(10),Duration.ofMinutes(1)));Instant n=Instant.parse("2026-07-25T00:00:00Z");assertTrue(g.allow("svc",n).allowed());assertFalse(g.allow("svc",n.plusSeconds(10)).allowed());g.failure("svc");g.failure("svc");assertFalse(g.allow("svc",n.plusSeconds(120)).allowed());}}